// Writes js/woodcut/gen/end-lyrics.js (the last chapter: 261.5 to the end) from source/lines.json. Run from the
// project folder:   node js/woodcut/end-make-lyrics.mjs
// The output quotes the lyric, so it lives under gen/ (gitignored). Never edit the generated file by hand.
import fs from 'fs';
const d = JSON.parse(fs.readFileSync('source/lines.json', 'utf8'));
const T0 = 261.5;
const lines = d.lines.filter(l => l.s >= T0 - 1e-6).map(l => ({ i: l.i, text: l.text, s: l.s, e: l.e, approx: !!l.approx, words: l.words.map(w => ({ w: w.w, s: w.s, e: w.e })) }));
for (const l of lines) if (l.words.map(w => w.w).join(' ') !== l.text) throw new Error('word list does not rebuild line ' + l.i);
fs.mkdirSync('js/woodcut/gen', { recursive: true });
fs.writeFileSync('js/woodcut/gen/end-lyrics.js', '// GENERATED by end-make-lyrics.mjs from source/lines.json (' + d.sha256.slice(0, 12) + '). Do not edit.\nconst LYE = ' + JSON.stringify(lines) + ';\n');
console.log(lines.length, 'lines', lines[0].i, '-', lines[lines.length - 1].i);
